<script lang="ts">
	import{onMount}from'svelte';let items=$state<any[]>([]),stateFilter=$state(''),loading=$state(true),error=$state('');
	async function load(){loading=true;error='';const r=await fetch(`/api/v1/ops/cases?state=${stateFilter}`,{credentials:'include'});const d=await r.json().catch(()=>({}));loading=false;if(!r.ok){error=d.detail??'Cases could not be loaded.';return}items=d.cases??[]};onMount(load);
</script>
<svelte:head><title>Support cases — Kredit admin</title></svelte:head>
<main class="shell workspace queue"><header><div><p class="eyebrow">Admin / Support</p><h1>Help people reach an answer.</h1><p>Every case keeps its full history, owner and reason.</p></div><label>Show<select bind:value={stateFilter} onchange={load}><option value="">All cases</option><option value="OPEN">Open</option><option value="IN_PROGRESS">Being handled</option><option value="RESOLVED">Resolved</option><option value="CLOSED">Closed</option></select></label></header>{#if error}<p class="error">{error}</p>{:else if loading}<p>Loading support cases…</p>{:else}<section>{#each items as item}<a href={`/admin/cases/${item.id}`}><span class:urgent={item.break_glass}>{item.break_glass?'Urgent access':'Support case'}</span><div><h2>{item.subject_type.replaceAll('_',' ')}</h2><p>{item.subject_id}</p><small>Updated {new Date(item.updated_at).toLocaleString('en-NG')}</small></div><strong>{item.state.replaceAll('_',' ')}</strong><b>→</b></a>{:else}<div class="empty-state"><h2>No cases in this view</h2><p>Choose another status or return later.</p></div>{/each}</section>{/if}</main>
<style>.queue>header{display:flex;align-items:end;justify-content:space-between;gap:2rem;padding:2rem 0;border-bottom:3px solid #17181b}.queue h1{margin:.4rem 0;font-family:Georgia,serif;font-size:clamp(2.5rem,6vw,4.5rem);font-weight:500;line-height:.95}.queue label{display:grid;gap:.35rem;font-size:.75rem;font-weight:800}.queue select{min-height:2.8rem;padding:.5rem;border:1px solid #17181b;background:#faf8f2}.queue section{display:grid}.queue section>a{display:grid;grid-template-columns:8rem 1fr auto auto;align-items:center;gap:1rem;padding:1.2rem 0;border-bottom:1px solid #bbb6ac;color:#17181b;text-decoration:none}.queue a>span{font-size:.7rem;font-weight:850;color:#2738d6}.queue .urgent{color:#9b351f}.queue h2{margin:0;font-family:Georgia,serif;font-size:1.35rem;font-weight:500;text-transform:capitalize}.queue p,.queue small{margin:.25rem 0;color:#66635e}.queue a>strong{font-size:.72rem;text-transform:capitalize}.queue a>b{color:#ff6848}@media(max-width:650px){.queue>header{align-items:stretch;flex-direction:column}.queue section>a{grid-template-columns:1fr auto}.queue a>span,.queue a>div{grid-column:1}.queue a>strong,.queue a>b{grid-column:2}.queue a>strong{grid-row:1}.queue a>b{grid-row:2}}</style>
